using Godot;
using System;
public partial class MigrationScene {
 void ItemAccessory(Node3D root,int slot,int tier){Color cloth=new(.28f,.32f,.24f),plate=new(.32f,.38f,.36f);if(slot==11){Ellipsoid(root,new(0,.30f,0),new(.19f,.16f,.17f),tier==1?cloth:plate);Box(root,new(0,.24f,-.13f),new(.32f,.04f,.15f),cloth);}else for(int sign=-1;sign<=1;sign+=2){if(slot==12){Ellipsoid(root,new(sign*.12f,.2f,0),new(.075f,.13f,.045f),cloth);Box(root,new(sign*.12f,.23f,-.04f),new(.12f,.10f,.025f),plate);}else{Box(root,new(sign*.13f,.16f,.02f),new(.16f,.27f,.19f),cloth);Box(root,new(sign*.13f,.06f,-.08f),new(.17f,.10f,.32f),plate);}}}
 int shownWoundCount;
 void ShowWounds(){shownWoundCount=game.Life.Wounds.Count;var b=Panel("FIELD MEDIC / WOUNDS");coopMenu="wounds";Text(b,"One untreated bite: 10 minutes. Two untreated bites drain twice as fast. H uses one bandage on the most urgent wound.\nA bandage pauses that wound's remaining blood timer. Keep it on for 20 active minutes to heal the wound. Removing it resumes the saved countdown and resets healing. Bandages never restore health.");var scroll=new ScrollContainer{CustomMinimumSize=new(880,350)};b.AddChild(scroll);var rows=new VBoxContainer();scroll.AddChild(rows);for(int i=0;i<game.Life.Wounds.Count;i++){int index=i;var w=game.Life.Wounds[i];var label=new Label();rows.AddChild(label);label.SetMeta("wound",i);if(w.Patched)Button(rows,"REMOVE BANDAGE / WOUND "+(i+1),()=>{if(!CoopRequest("unpatch",index.ToString()))game.Change(()=>game.Life.Unpatch(index));ShowWounds();});}if(game.Life.Wounds.Count==0)Text(rows,"No wounds. Stay fed and hydrated for slow natural recovery.");Button(b,"PATCH MOST URGENT WOUND",()=>{if(!CoopRequest("bandage"))game.Change(()=>game.Life.Patch());ShowWounds();});Button(b,"BACK",CloseMenu);UpdateWoundPanel();}
 void UpdateWoundPanel(){if(coopMenu!="wounds"||menu==null)return;if(shownWoundCount!=game.Life.Wounds.Count){ShowWounds();return;}int open=game.Life.Wounds.FindAll(w=>!w.Patched).Count;foreach(var node in menu.FindChildren("*","Label",true,false))if(node is Label l&&l.HasMeta("wound")){int i=(int)l.GetMeta("wound");if(i>=game.Life.Wounds.Count){l.Text="WOUND HEALED";continue;}var w=game.Life.Wounds[i];string time(double n)=>TimeSpan.FromSeconds(Math.Max(0,n)).ToString(@"mm\:ss");l.Text=$"WOUND {i+1} / "+(w.Patched?$"BANDAGED / bleed timer paused at {time(w.Blood)} / heals in {time(w.Recovery)}":$"OPEN / fatal bleed in {time(w.Blood/Math.Max(1,open))}");}}
}
